import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.logging.Logger;

public class UserProfileServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(UserProfileServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String userId = req.getParameter("id");
        String fields = req.getParameter("fields");

        // Validate userId is numeric
        if (userId == null || !userId.matches("^[0-9]+$")) {
            resp.sendError(400, "Invalid user ID");
            return;
        }

        // Fields parameter allows selecting which columns to return
        // Default to safe set if not specified
        if (fields == null || fields.isEmpty()) {
            fields = "username, email, created_at";
        } else {
            // Basic validation: only allow alphanumeric, commas, spaces, underscores
            // This is intended to prevent injection but the regex is flawed
            fields = fields.replaceAll("[^a-zA-Z0-9_,\\s()]", "");
        }

        String query = "SELECT " + fields + " FROM user_profiles WHERE user_id = " + userId;
        log.info("Executing query: " + query);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("{");
            ResultSetMetaData meta = rs.getMetaData();

            if (rs.next()) {
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    if (i > 1) json.append(",");
                    json.append("\"")
                        .append(meta.getColumnLabel(i))
                        .append("\":\"")
                        .append(rs.getString(i) != null ? rs.getString(i).replace("\"", "\\\"") : "null")
                        .append("\"");
                }
            }
            json.append("}");
            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            log.warning("SQL error: " + e.getMessage());
            resp.sendError(500, "Database error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Update profile - uses PreparedStatement (safe)
        String userId = req.getParameter("id");
        String bio = req.getParameter("bio");
        String website = req.getParameter("website");

        if (userId == null || !userId.matches("^[0-9]+$")) {
            resp.sendError(400, "Invalid user ID");
            return;
        }

        String updateSql = "UPDATE user_profiles SET bio = ?, website = ? WHERE user_id = ?";
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement pstmt = conn.prepareStatement(updateSql)) {
            pstmt.setString(1, bio);
            pstmt.setString(2, website);
            pstmt.setInt(3, Integer.parseInt(userId));
            pstmt.executeUpdate();
            resp.setStatus(200);
            resp.getWriter().write("{\"status\":\"updated\"}");
        } catch (SQLException e) {
            log.warning("SQL error: " + e.getMessage());
            resp.sendError(500, "Database error");
        }
    }
}
